CREATE TABLE "User" ("id" TEXT NOT NULL PRIMARY KEY, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" TEXT NOT NULL DEFAULT 'CUSTOMER', "emailVerifiedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "CustomerProfile" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "legalName" TEXT, "phone" TEXT, "residentialAddress" TEXT, "institution" TEXT, "studentNumber" TEXT, CONSTRAINT "CustomerProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "CustomerProfile_userId_key" ON "CustomerProfile"("userId");
CREATE TABLE "LoanProduct" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "description" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT false, "minCents" INTEGER NOT NULL, "maxCents" INTEGER NOT NULL, "periodsJson" TEXT NOT NULL, "pricingJson" TEXT NOT NULL, "effectiveFrom" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "LoanApplication" ("id" TEXT NOT NULL PRIMARY KEY, "reference" TEXT NOT NULL, "userId" TEXT NOT NULL, "productId" TEXT, "status" TEXT NOT NULL DEFAULT 'DRAFT', "requestedCents" INTEGER, "periodMonths" INTEGER, "personalJson" TEXT, "financialJson" TEXT, "submittedAt" DATETIME, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "LoanApplication_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "LoanApplication_productId_fkey" FOREIGN KEY ("productId") REFERENCES "LoanProduct"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE UNIQUE INDEX "LoanApplication_reference_key" ON "LoanApplication"("reference");
CREATE TABLE "ApplicationStatusHistory" ("id" TEXT NOT NULL PRIMARY KEY, "applicationId" TEXT NOT NULL, "status" TEXT NOT NULL, "note" TEXT, "actorId" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ApplicationStatusHistory_applicationId_fkey" FOREIGN KEY ("applicationId") REFERENCES "LoanApplication"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Document" ("id" TEXT NOT NULL PRIMARY KEY, "applicationId" TEXT NOT NULL, "name" TEXT NOT NULL, "storageKey" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Document_applicationId_fkey" FOREIGN KEY ("applicationId") REFERENCES "LoanApplication"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "Consent" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "type" TEXT NOT NULL, "version" TEXT NOT NULL, "acceptedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Consent_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL PRIMARY KEY, "actorId" TEXT NOT NULL, "action" TEXT NOT NULL, "subjectType" TEXT NOT NULL, "subjectId" TEXT NOT NULL, "metadata" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "SupportTicket" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT, "email" TEXT NOT NULL, "subject" TEXT NOT NULL, "message" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'OPEN', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Payment" ("id" TEXT NOT NULL PRIMARY KEY, "applicationId" TEXT, "amountCents" INTEGER NOT NULL, "status" TEXT NOT NULL, "providerRef" TEXT, "idempotencyKey" TEXT NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "Payment_idempotencyKey_key" ON "Payment"("idempotencyKey");
